let payload = msg.payload;

if (typeof payload === "string") {
    payload = JSON.parse(payload);
}

if (!payload || !Array.isArray(payload.data)) {
    node.error("No se encuentra el array de cartas", msg);
    return null;
}

const cards = [];
const messages = [];
const now = new Date().toISOString();

for (const card of payload.data) {
    const price = card.prices?.eur;

    if (price === null || price === undefined || price === "") {
        continue;
    }

    const numericPrice = Number(price);
    if (!Number.isFinite(numericPrice)) {
        continue;
    }

    const item = {
        card_id: card.id,
        name: card.name,
        image_url: card.image_uris?.normal || card.card_faces?.[0]?.image_uris?.normal || "",
        set: card.set,
        rarity: card.rarity,
        price: numericPrice,
        currency: "EUR"
    };

    cards.push(item);

    messages.push({
        payload: {
            card_id: item.card_id,
            name: item.name,
            image_url: item.image_url,
            set: item.set,
            rarity: item.rarity,
            price: numericPrice,
            currency: "EUR",
            timestamp: new Date().toISOString(),
            source: "simulation",
            mode: "simulated"
        }
    });
}

// Guardar las cartas en contexto GLOBAL
global.set("cards", cards);

node.warn("Cartas guardadas: " + cards.length);

if (messages.length === 0) {
    return null;
}

// Envía una carta por mensaje hacia el siguiente nodo (Producer)
return [messages];

const card = msg.payload;

// Guardamos el último precio conocido de cada carta
let lastPrices = context.get("lastPrices") || {};

// Identificamos la carta
const id = card.card_id;
const newPrice = Number(card.price);

// Validaciones
if (!id || !Number.isFinite(newPrice) || newPrice <= 0) {
    return null;
}

// Primera vez que vemos la carta:
// guardamos el precio, pero NO enviamos ningún mensaje
if (lastPrices[id] === undefined) {
    lastPrices[id] = newPrice;
    context.set("lastPrices", lastPrices);
    return null;
}

// Comparamos con el precio anterior
const oldPrice = lastPrices[id];

const changePercent =
    ((newPrice - oldPrice) / oldPrice) * 100;

// Actualizamos el precio guardado
lastPrices[id] = newPrice;
context.set("lastPrices", lastPrices);

// Si supera el 20 %, generamos alerta
if (Math.abs(changePercent) > 20) {
    msg.key = id;
    msg.payload = {
        card_id: id,
        name: card.name,
        set: card.set,
        old_price: oldPrice,
        new_price: newPrice,
        currency: card.currency || "EUR",
        change_percent: Number(changePercent.toFixed(2)),
        image_url: card.image_url || "",
        timestamp: card.timestamp || new Date().toISOString(),
        alert: "PRICE_ANOMALY"
    };
    return msg;
}

return null;

let cards = global.get("cards");

if (!cards || cards.length === 0) {
    return null;
}

let sim = context.get("simState") || {
    tick: 0,
    nextEvent: {}
};

sim.tick++;

const messages = [];

const specialCards = [
    "Teferi's Protection",
    "Sheoldred, the Apocalypse"
];

function randomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

for (const card of cards) {

    const id = card.card_id;
    const oldPrice = Number(card.price);

    if (!id || !Number.isFinite(oldPrice) || oldPrice <= 0) {
        continue;
    }

    const isSpecial = specialCards.includes(card.name);

    // Variación habitual: entre -0,9 % y +0,9 %
    const normalVariation = (Math.random() * 1.8 - 0.9) / 100;

    let newPrice = oldPrice * (1 + normalVariation);

    // Pequeños movimientos bruscos para dar dinamismo
    const smallJumpProbability = isSpecial ? 0.12 : 0.04;

    if (Math.random() < smallJumpProbability) {

        const jump = (1.5 + Math.random() * 3) / 100;
        const direction = Math.random() < 0.5 ? 1 : -1;

        newPrice *= (1 + direction * jump);
    }

    // Las dos cartas protagonistas tienen anomalías programadas
    if (isSpecial) {

        if (sim.nextEvent[id] === undefined) {
            sim.nextEvent[id] = sim.tick + randomInt(12, 22);
        }

        if (sim.tick >= sim.nextEvent[id]) {

            const jump = (25 + Math.random() * 10) / 100;
            const direction = Math.random() < 0.5 ? 1 : -1;

            newPrice = oldPrice * (1 + direction * jump);


            // Siguiente anomalía independiente
            sim.nextEvent[id] = sim.tick + randomInt(12, 22);
        }
    }

    // Las demás cartas pueden tener alguna anomalía inesperada
    else if (Math.random() < 0.0025) {

        const jump = (25 + Math.random() * 10) / 100;
        const direction = Math.random() < 0.5 ? 1 : -1;

        newPrice = oldPrice * (1 + direction * jump);

        node.warn(
            "ANOMALÍA INESPERADA: " + card.name +
            " | " + (direction > 0 ? "SUBIDA" : "BAJADA") +
            " del " + (jump * 100).toFixed(2) + "%"
        );
    }

    newPrice = Math.max(0.01, Number(newPrice.toFixed(2)));

    card.price = newPrice;

    messages.push({
        payload: {
            card_id: card.card_id,
            name: card.name,
            image_url: card.image_url,
            set: card.set,
            rarity: card.rarity,
            price: newPrice,
            currency: "EUR",
            timestamp: new Date().toISOString(),
            source: "simulation",
            mode: "simulated"
        }
    });
}

global.set("cards", cards);
context.set("simState", sim);

return [messages];

let store = flow.get("historyStore") || {};
let selectedId = flow.get("selectedCardId") || null;

// CASE A: user has selected another card to visualize
if (typeof msg.payload === "string") {
    selectedId = msg.payload;
    flow.set("selectedCardId", selectedId);

    const cardData = store[selectedId];
    if (!cardData) return [null, null, null];

    const chartMsg = {
        topic: `${cardData.name} (${cardData.set.toUpperCase()})`,
        payload: cardData.points
    };
    const imageMsg = {
        topic: cardData.name,
        payload: cardData.image_url || ""
    };
    return [null, chartMsg, null, imageMsg];
}

// CASE B: card price update
const card = msg.payload;
if (!card || !card.card_id || typeof card.price !== "number") {
    return [null, null, null];
}

const id = card.card_id;
const timeMs = card.timestamp ? new Date(card.timestamp).getTime() : Date.now();
let isNewCard = false;

// if card is new initialize history
if (!store[id]) {
    isNewCard = true;
    store[id] = {
        card_id: id,
        name: card.name,
        set: card.set,
        image_url: card.image_url || "",
        initialPrice: card.price,
        currentPrice: card.price,
        points: []
    };
} else if (!store[id].image_url && card.image_url) {
    store[id].image_url = card.image_url;
}

// Price update
store[id].currentPrice = card.price;
store[id].points.push({ x: timeMs, y: card.price });
if (store[id].points.length > 50) {
    store[id].points.shift();
}

// if there is no card selected, the first one to arrive is selected
if (!selectedId) {
    selectedId = id;
    flow.set("selectedCardId", selectedId);
}

flow.set("historyStore", store);

// OUTPUT 1: option update
let dropdownMsg = null;
if (isNewCard) {
    const options = Object.values(store)
        .map( c=> ({ label: `${c.name} (${c.set.toUpperCase()})`, value: c.card_id}))
        .sort((a, b) => a.label.localeCompare(b.label));
    dropdownMsg = { options: options };
}

// OUTPUT 2: graph update
let chartMsg = null;
let imageMsg = null;
if (id === selectedId) {
    chartMsg = {
        topic: `${store[id].name} (${store[id].set.toUpperCase()})`,
        payload: store[id].points
    };
    imageMsg = {
        topic: store[id].name,
        payload: store[id].image_url || ""
    }
}

// OUTPUT 3: Top 10 best rises
const ranking = Object.values(store)
    .map(c => {
        const diffPct = ((c.currentPrice - c.initialPrice) / c.initialPrice) * 100;
        return {
            Card: c.name,
            Set: c.set.toUpperCase(),
            "Initial (€)": c.initialPrice.toFixed(2),
            "Current (€)": c.currentPrice.toFixed(2),
            "Difference (€)": Number(diffPct.toFixed(2)),
        };
    })
    .sort((a, b) => b["Difference (%)"] - a["Difference (%)"])
    .slice(0, 10);

const tableMsg = { payload: ranking };

return [dropdownMsg, chartMsg, tableMsg, imageMsg];

const alertData =
  typeof msg.payload === "string"
    ? JSON.parse(msg.payload)
    : msg.payload;

if (!alertData || typeof alertData !== "object") {
  return null;
}

const currency = alertData.currency || "EUR";
const pct = Number(alertData.change_percent ?? 0);
const subida = pct > 0;

const cardName = alertData.name || "Unknown card";
const price = Number(alertData.new_price);

const point = subida ? "🔴" : "🟢";
const status = subida ? "PRICE INCREASE" : "PRICE DECREASE";
const arrow = subida ? "▲" : "▼";
const sign = pct > 0 ? "+" : "";

const priceText = Number.isFinite(price)
  ? `${price.toFixed(2)} ${currency}`
  : "Not available";

const telegramText =
  `${point} <b>${status}</b>\n\n` +
  `🃏 <b>${cardName}</b>\n\n` +
  `💰 <b>${priceText}</b>\n\n` +
  `<b>${arrow} ${sign}${pct.toFixed(2)}%</b>`;

const TOKEN = env.get("TELEGRAM_TOKEN");
const CHAT_ID = env.get("TELEGRAM_CHAT_ID");

if (!TOKEN || !CHAT_ID) {
  node.error("Missing TELEGRAM_TOKEN or TELEGRAM_CHAT_ID");
  return null;
}

msg.method = "POST";
msg.url = `https://api.telegram.org/bot${TOKEN}/sendMessage`;
msg.headers = {
  "Content-Type": "application/json"
};

msg.payload = {
  chat_id: CHAT_ID,
  text: telegramText,
  parse_mode: "HTML"
};

return msg;

const texto = typeof msg.payload === "string" ? msg.payload : "";

if (!texto.trim()) {
    node.status({ fill: "red", shape: "ring", text: "Texto vacío" });
    node.error("msg.payload está vacío o no es un string. Revisa la ruta en file in.", msg);
    return null;
}

const lineas = texto.split(/\r?\n/);
const identificadores = [];
const vistos = new Set();
const sinMatch = [];

for (const rawLinea of lineas) {
    const linea = rawLinea.trim();
    if (!linea) continue;

    // Coincide con líneas tipo:
    // "1 Ognis, the Dragon's Lash (PSNC) 210p"
    // "1 Blasphemous Act (PLST) DRC-101"
    // "1 Full Throttle (PDFT) 127s *F*"
    const match = linea.match(/^\d+\s+(.+?)\s+\(([A-Za-z0-9]+)\)\s+([A-Za-z0-9-]+)(?:\s+\*([A-Za-z0-9]+)\*)?$/);

    if (!match) {
        sinMatch.push(linea);
        continue;
    }

    const set = match[2].toLowerCase();
    const collector_number = match[3];
    const clave = `${set}:${collector_number.toLowerCase()}`;

    if (!vistos.has(clave)) {
        vistos.add(clave);
        identificadores.push({ set, collector_number });
    }
}

if (sinMatch.length > 0) {
    node.warn(`Líneas no reconocidas (${sinMatch.length}): ${sinMatch.join(" | ")}`);
}

const TAMANO_LOTE = 75;
const lotes = [];

for (let i = 0; i < identificadores.length; i += TAMANO_LOTE) {
    lotes.push({
        headers: {
            "User-Agent": "MTGRadarNodeRED/1.0",
            "Accept": "application/json",
            "Content-Type": "application/json"
        },
        payload: {
            identifiers: identificadores.slice(i, i + TAMANO_LOTE)
        }
    });
}

node.status({
    fill: "green",
    shape: "dot",
    text: `${identificadores.length} cartas · ${lotes.length} lote(s)`
});

// En esta prueba devolvemos el primer lote (o un array de lotes) al debug
return lotes.length === 1 ? lotes[0] : [lotes];

const text = String(msg.payload?.content || "").trim();

// Detect the /cards command
if (!/^\/cards(@\w+)?$/i.test(text)) {
    return null;
}

// Retrieve information
const chatId = msg.payload.chatId;
const cards = global.get("cards") || [];
const TOKEN = env.get("TELEGRAM_TOKEN");

// Check token
if (!TOKEN) {
    node.error("TELEGRAM_TOKEN not found");
    return null;
}

// Check that cards are available
if (!Array.isArray(cards) || cards.length === 0) {
    node.warn("No cards loaded in global.cards");
    return null;
}

// Create keyboard with one button per row
const keyboard = [];

cards.slice(0, 40).forEach(card => {

    const name = card.name || "Unknown card";

    const set = card.set
        ? ` (${card.set.toUpperCase()})`
        : "";

    keyboard.push([
        {
            text: `${name}${set}`,
            callback_data: "card:" + card.card_id
        }
    ]);
});

// Prepare Telegram request
msg.method = "POST";

msg.url =
    `https://api.telegram.org/bot${TOKEN}/sendMessage`;

msg.headers = {
    "Content-Type": "application/json"
};

msg.payload = {
    chat_id: chatId,
    text:
        "🃏 PRICE LOOKUP\n\nSelect the card whose price you want to check:",
    reply_markup: {
        inline_keyboard: keyboard
    }
};

return msg;

const data = msg.payload?.content;
const chatId = msg.payload?.chatId;

if (!data || chatId === undefined || !data.startsWith("card:")) {
    return null;
}

const cardId = data.substring(5);
const cards = global.get("cards") || [];
const card = cards.find(c => c.card_id === cardId);

if (!card) {
    node.warn("Card not found: " + cardId);
    return null;
}

// Current price
const price = Number(card.price);

// Find image
const image =
    card.image_uris?.small ||
    card.image_uris?.normal ||
    card.image ||
    card.image_url;

const TOKEN = env.get("TELEGRAM_TOKEN");

if (!TOKEN) {
    node.error("TELEGRAM_TOKEN not found");
    return null;
}

// Caption accompanying the image
const priceText = Number.isFinite(price)
    ? `💰 CURRENT PRICE: ${price.toFixed(2)} €`
    : "💰 Price not available";

const text =
    `🃏 ${card.name}\n\n` +
    `📦 Set: ${(card.set || "N/A").toUpperCase()}\n` +
    `💎 Rarity: ${card.rarity || "N/A"}\n\n` +
    priceText;

// If an image exists, send a photo
if (image) {
    msg.url = `https://api.telegram.org/bot${TOKEN}/sendPhoto`;
    msg.payload = {
        chat_id: chatId,
        photo: image,
        caption: text
    };
} else {
    // If no image exists, send text only
    msg.url = `https://api.telegram.org/bot${TOKEN}/sendMessage`;
    msg.payload = {
        chat_id: chatId,
        text: text
    };
}

msg.method = "POST";
msg.headers = {
    "Content-Type": "application/json"
};

return msg;
